function currentAchLevel(a){let v=a.value(),n=0;while(n<a.levels.length&&v>=a.levels[n])n++;return n}
function syncAchievements(showToast=false){let gained=0;for(const a of ACHIEVEMENTS){let now=currentAchLevel(a),was=state.achievementLevels[a.id]||0;if(now>was){for(let i=was;i<now;i++)gained+=a.reward[i]||0;state.achievementLevels[a.id]=now}}if(gained){state.coins+=gained;if(showToast)setTimeout(()=>alert(`🏆 Achievement level up! +${gained} Boost Coins`),80)}return gained}
function missionCoinReward(){let d=new Date().toISOString().slice(0,10);if(state.dailyCoins.date!==d)state.dailyCoins={date:d,missions:0};let rewards=[100,75,50],n=state.dailyCoins.missions++,r=rewards[n]??25;return r}
function equippedItem(type){return SHOP_ITEMS.find(x=>x.id===state.equipped[type])||SHOP_ITEMS.find(x=>x.type===type&&x.price===0)}
function applyAppTheme(){let id=equippedItem("theme")?.id||"theme_default";document.body.classList.remove("app-theme-space","app-theme-arcade","app-theme-ocean","app-theme-fire","app-theme-cosmic","app-theme-diamond","app-theme-forest","app-theme-sunset","app-theme-aurora","app-theme-void","app-theme-candy","app-theme-mint","app-theme-gold");if(id==="theme_space")document.body.classList.add("app-theme-space");if(id==="theme_arcade")document.body.classList.add("app-theme-arcade");if(id==="theme_ocean")document.body.classList.add("app-theme-ocean");if(id==="theme_fire")document.body.classList.add("app-theme-fire");if(id==="theme_cosmic")document.body.classList.add("app-theme-cosmic");if(id==="theme_diamond")document.body.classList.add("app-theme-diamond");if(id==="theme_forest")document.body.classList.add("app-theme-forest");if(id==="theme_sunset")document.body.classList.add("app-theme-sunset");if(id==="theme_aurora")document.body.classList.add("app-theme-aurora");if(id==="theme_void")document.body.classList.add("app-theme-void");if(id==="theme_candy")document.body.classList.add("app-theme-candy");if(id==="theme_mint")document.body.classList.add("app-theme-mint");if(id==="theme_gold")document.body.classList.add("app-theme-gold");document.documentElement.setAttribute("data-gcse-theme",id)}

function displayAvatar(){return equippedItem("avatar")?.icon||learnerAvatar()}
function avatarDecorHTML(big=false){let av=equippedItem("avatar"),fr=equippedItem("frame"),title=equippedItem("title"),fc=fr&&fr.id!=="frame_none"?" "+fr.id:"",anim=av?.animated?" avatar-animated":"";return `<div class="avatar-wrap${fc}${anim}"><span class="${big?"shop-avatar-big":"shop-avatar"}">${escapeHtml(av?.icon||learnerAvatar())}</span></div>${title&&title.id!=="title_none"?`<span class="equipped-title">${escapeHtml(title.name)}</span>`:""}`}
function buyOrEquip(id){let item=SHOP_ITEMS.find(x=>x.id===id);if(!item)return;if(!state.ownedShop.includes(id)){if(!isTestLearner()&&state.coins<item.price){alert(`You need ${item.price-state.coins} more Boost Coins 🪙`);return}if(!isTestLearner())state.coins-=item.price;state.ownedShop.push(id)}state.equipped[item.type]=id;if(item.type==="avatar")state.profile={...(state.profile||{}),avatar:item.icon};applyAppTheme();save();showShop()}
function shopHTML(){
  const types=[["avatar","👤","Avatars","Show your style"],["frame","▣","Frames","Stand out"],["theme","🎨","Themes","Change the look"],["title","👑","Titles","Earn and display"]];
  const active=window.gcseShopTab||"avatar";
  const balance=coinBalance();
  const rarityRank={"Common":1,"Rare":2,"Epic":3,"Legendary":4,"Ultra Rare":5};
  const items=SHOP_ITEMS.filter(x=>x.type===active).slice().sort((a,b)=>(a.price-b.price)||(rarityRank[a.rarity]-rarityRank[b.rarity]));
  const current=equippedItem(active);
  const itemCard=x=>{
    const owned=state.ownedShop.includes(x.id)||x.price===0;
    const equipped=state.equipped[x.type]===x.id;
    const can=balance>=x.price;
    const rarity=(x.rarity||"Common").toLowerCase().replace(/\s+/g,"-");
    return `<div class="shop-v2-item rarity-${rarity}">
      <div class="shop-v2-icon ${x.type==="frame"?x.id:""} ${x.animated?"avatarFloat":""}">${escapeHtml(x.icon)}</div>
      <div class="shop-v2-name">${escapeHtml(x.name)}</div>
      <div class="shop-v2-rarity">${escapeHtml(x.rarity||"Common")}</div>
      <div class="shop-v2-price">🪙 ${Number(x.price).toLocaleString()}</div>
      <button class="${equipped?"shop-equipped":owned?"shop-owned":"shop-buy"}" ${(!owned&&!can)?"disabled":""} onclick="buyOrEquip('${x.id}')">${equipped?"EQUIPPED":owned?"EQUIP":"BUY"}</button>
    </div>`;
  };
  const groups=["Common","Rare","Epic","Legendary","Ultra Rare"].map(r=>{
    const arr=items.filter(x=>(x.rarity||"Common")===r);
    if(!arr.length)return "";
    const cls=r.toLowerCase().replace(/\s+/g,"-");
    return `<section class="shop-v2-tier tier-${cls}">
      <div class="shop-v2-tierhead"><span>${r==="Ultra Rare"?"💎":r==="Legendary"?"👑":r==="Epic"?"✨":r==="Rare"?"🔷":"⚪"} ${escapeHtml(r)}</span><small>${r==="Ultra Rare"?"The ultimate rewards":r==="Legendary"?"Truly special":r==="Epic"?"Level up":r==="Rare"?"Stand out":"Great start"}</small></div>
      <div class="shop-v2-grid">${arr.map(itemCard).join("")}</div>
    </section>`;
  }).join("");
  return `<div class="shop-v2-shell">
    <header class="shop-v2-header">
      <button class="shop-v2-home" onclick="goHome()">← Home</button>
      <div class="shop-v2-brand"><b>🛍️ BOOST SHOP</b><span>Make learning your style</span></div>
      <div class="shop-v2-balance">🪙 ${Number(balance).toLocaleString()}</div>
    </header>
    <div class="shop-v2-tabs">${types.map(([id,ico,name])=>`<button class="${active===id?"active":""}" onclick="window.gcseShopTab='${id}';showShop()">${ico}<span>${name}</span></button>`).join("")}</div>
    <div class="shop-v2-layout">
      <aside class="shop-v2-side">
        ${types.map(([id,ico,name,sub])=>`<button class="${active===id?"active":""}" onclick="window.gcseShopTab='${id}';showShop()"><b>${ico} ${name}</b><small>${sub}</small></button>`).join("")}
        <div class="shop-v2-tip"><b>🏆 High Prices = Rarer Items</b><p>Items are organised from lowest to highest price in each category.</p><span>🪙 Collect coins and work your way up!</span></div>
      </aside>
      <main class="shop-v2-main">
        <div class="shop-v2-title"><div><b>${types.find(x=>x[0]===active)[1]} ${types.find(x=>x[0]===active)[2]}</b><span>${types.find(x=>x[0]===active)[3]}</span></div><small>📶 Sorted by price: Low → High</small></div>
        <div class="shop-v2-preview">${avatarDecorHTML()}<div><b>Your current style</b><span>${current?escapeHtml(current.name):""}</span></div></div>
        ${groups}
      </main>
    </div>
  </div>`;
}
function showShop(){openOverlay("shopOverlay",shopHTML())}
function achievementHTML(){return ACHIEVEMENTS.map(a=>{let v=a.value(),lvl=currentAchLevel(a),idx=Math.min(lvl,a.levels.length-1),done=lvl>=a.levels.length,target=done?a.levels.at(-1):a.levels[lvl],prev=lvl? a.levels[lvl-1]:0,pc=done?100:Math.max(0,Math.min(100,Math.round((v-prev)*100/(target-prev)))),label=done?"Diamond":lvl?a.labels[lvl-1]:"Starting";return `<div class="achievement-progress"><div class="achievement-head"><span>${a.icon} <b>${a.name}</b></span><strong>${label}</strong></div><div class="achievement-bar"><i style="width:${pc}%"></i></div><small>${v}${a.unit==="%"?"%":" "+a.unit} · ${done?"Maximum level":`${Math.max(0,target-v)} to ${a.labels[lvl]}`}</small></div>`}).join("")}

function save(){try{localStorage.setItem(KEY,JSON.stringify(state))}catch(e){};saveActiveSession();try{window.gcseCloudQueueSave?.()}catch(e){}}

// V0.11B.2 cloud bridge. Cloud auth stays in a separate module; the learning engine
// only exposes a safe snapshot/restore boundary.
window.gcseBoostGetState=()=>JSON.parse(JSON.stringify(state));
window.gcseBoostGetLearner=()=>{const l=activeLearner();return l?JSON.parse(JSON.stringify(l)):null};
window.gcseBoostApplyCloudState=(cloudState,scalars={})=>{
  const incoming=(cloudState&&typeof cloudState==="object")?cloudState:{};
  state=Object.assign(fresh(),incoming);
  if(scalars.xp!=null)state.xp=Number(scalars.xp)||0;
  if(scalars.coins!=null)state.coins=Number(scalars.coins)||0;
  if(scalars.streak!=null)state.streak=Number(scalars.streak)||0;
  if(scalars.lives!=null)state.lives=Number.isFinite(Number(scalars.lives))?Number(scalars.lives):3;
  if(scalars.missions!=null)state.missions=Number(scalars.missions)||0;
  if(scalars.boss_wins!=null)state.bossWins=Number(scalars.boss_wins)||0;
  state.schoolSchedule=state.schoolSchedule||{Monday:[],Tuesday:[],Wednesday:[],Thursday:[],Friday:[]};
  try{localStorage.setItem(KEY,JSON.stringify(state))}catch(e){}
  try{
    if(session&&session.qs&&session.index<session.qs.length){
      show("lesson");
    }else{
      home();
    }
  }catch(e){}
};
function show(id){document.querySelectorAll(".screen").forEach(x=>x.classList.add("hidden"));$(id)?.classList.remove("hidden")}
const SCHOOL_DAYS=["Monday","Tuesday","Wednesday","Thursday","Friday"];
const SCHOOL_SUBJECTS=["Maths","English","Science","History","Geography","German","Spanish","Drama","Citizenship","Sport Science","Catering","RE"];
function schoolDayName(){return ["Sunday","Monday","Tuesday","Wednesday","Thursday","Friday","Saturday"][new Date().getDay()]}
function todaysSchoolSubjects(){let d=schoolDayName();return Array.isArray(state.schoolSchedule?.[d])?state.schoolSchedule[d]:[]}
function missionSubjectScore(sub){
 let st=subjectStats(sub), recent=(state.history||[]).slice(-80), last=[...recent].reverse().findIndex(x=>x.subject===sub);
 let weak=st.n?Math.max(0,100-st.acc):35, overdue=last<0?30:Math.min(30,last*3), school=todaysSchoolSubjects().includes(sub)?80:0;
 return school+weak+overdue+Math.random()*12;
}
function todaySubject(){
 let school=todaysSchoolSubjects(), candidates=school.length?school:SCHOOL_SUBJECTS;
 let usable=candidates.filter(x=>pool(x).length);
 if(!usable.length)usable=SCHOOL_SUBJECTS.filter(x=>pool(x).length);
 return usable.sort((a,b)=>missionSubjectScore(b)-missionSubjectScore(a))[0]||"Maths";
}
function todaySchoolHTML(){
 let d=schoolDayName(),subs=todaysSchoolSubjects();
 if(!SCHOOL_DAYS.includes(d))return `<div class="school-today"><b>🏫 School schedule</b><span>Weekend · today's mission uses your learning progress.</span></div>`;
 if(!subs.length)return `<div class="school-today"><b>🏫 ${d} at school</b><span>No lessons added yet · set your schedule in Profile.</span></div>`;
 return `<div class="school-today"><b>🏫 ${d} at school</b><span>${subs.map(escapeHtml).join(" · ")}</span></div>`;
}

const norm=v=>String(v??"").toLowerCase().trim().replace(/[’']/g,"").replace(/[£,%]/g,"").replace(/[^\w.\-\/ ]/g," ").replace(/\s+/g," ").trim();
const toks=v=>norm(v).split(" ").filter(x=>x.length>2&&!["the","and","that","with","from","into","this","they","are","was","were","for"].includes(x));
function closeText(a,b){const A=norm(a),B=norm(b);if(!A||!B)return false;if(A===B||A.includes(B)||B.includes(A))return true;const aa=new Set(toks(A)),bb=new Set(toks(B));let hit=0;aa.forEach(x=>{if(bb.has(x))hit++});return hit>=Math.max(1,Math.ceil(Math.min(aa.size,bb.size)*.6))}
function questionFingerprint(q){let stem=norm(q.q||q.prompt||"").replace(/\bscenario\s*\d+\b/g,"").replace(/\d+(?:\.\d+)?/g,"#").replace(/\s+/g," ").trim();return `${q.subject||""}|${q.topic||""}|${stem}`}
function recentFingerprints(limit=100){return new Set((state.served||[]).slice(-limit).map(x=>x.fp))}
function recordServed(q){if(!state.served)state.served=[];state.served.push({fp:questionFingerprint(q),pattern:varietyPattern(q),subject:q.subject,topic:q.topic,category:categoryFor(q),date:Date.now()});state.served=state.served.slice(-600);save()}
function diversePick(pool,count){let recent=recentFingerprints(100),seenPatterns=new Set(),seenQuestions=new Set(),out=[],sh=[...pool].sort(()=>Math.random()-.5);for(const q of sh){let fp=questionFingerprint(q),exact=norm(q.prompt)+"|"+(q.topic||"");if(seenPatterns.has(fp)||recent.has(fp)||seenQuestions.has(exact))continue;seenPatterns.add(fp);seenQuestions.add(exact);out.push(q);if(out.length>=count)break}if(out.length<count){for(const q of sh){let exact=norm(q.prompt)+"|"+(q.topic||"");if(seenQuestions.has(exact))continue;seenQuestions.add(exact);out.push(q);if(out.length>=count)break}}return out}
function normalise(q){const x={...q};x.prompt=q.q||q.question||q.prompt||"Question";x.choices=Array.isArray(q.a)?q.a:(Array.isArray(q.options)?q.options:(Array.isArray(q.answers)?q.answers:(Array.isArray(q.choices)?q.choices:[])));x.kind=x.choices.length>=2?"mcq":(q.type==="typed_text"||q.type==="written"?"written":"short");if(x.kind==="mcq"){if(typeof q.correct==="number")x.correctIndex=q.correct;else{x.correctIndex=x.choices.findIndex(v=>closeText(v,q.correct??q.answer));}}x.expected=q.answer??q.correctAnswer??(x.kind==="mcq"?x.choices[x.correctIndex]:q.correct);x.explanation=q.why||q.explanation||q.explain||"";return x}

const CATEGORY_GROUPS={
 "Maths":{"Number":["Number","Division"],"Algebra":["Algebra","Graphs","Quadratics","Functions","Simultaneous equations"],"Ratio, Proportion & Rates of Change":["Percentages","Ratio","Proportion","Rates of change"],"Geometry & Measures":["Area","Pythagoras","Geometry","Measures","Trigonometry","Vectors","Bearings","Transformations"],"Probability":["Probability"],"Statistics":["Statistics"]},
 "Science":{"Biology":["Biology"],"Chemistry":["Chemistry"],"Physics":["Physics"],"Working Scientifically":["Working Scientifically"]},
 "English":{"Reading":["Reading","Retrieval","Inference"],"Language":["Language"],"Structure":["Structure"],"Evaluation":["Evaluation"],"Writing":["Writing"]},
 "Geography":{"Physical Geography":["Physical"],"Human Geography":["Human"],"Geographical Skills":["Skills","Fieldwork"]},
 "German":{"Vocabulary":["Vocabulary"],"Grammar":["Grammar"],"Reading & Translation":["Reading","Translation"],"Writing":["Writing"]},
 "Spanish":{"Vocabulary":["Vocabulary"],"Grammar":["Grammar"],"Reading & Translation":["Reading","Translation"],"Writing":["Writing"]},
 "Drama":{"Devising":["Devising"],"Performance":["Performance"],"Response":["Response"]},
 "Citizenship":{"Citizenship Knowledge":["Citizenship","Rights","Law","Government","Democracy"],"Active Citizenship":["Active"],"Skills":["Skills"]},
 "Sport Science":{"Injury & Medical Conditions":["Injury","Medical"],"Training & Performance":["Training","Fitness","Performance"],"Sport Science Application":["Nutrition","Technology","Body"]},
 "Catering":{"Hospitality Industry":["Industry","Hospitality"],"Food Safety & Nutrition":["Safety","Nutrition"],"Practical Catering":["Practical","Cooking","Menu"]},
 "History":{"Thematic Study":["Crime","Punishment","Medicine","Warfare","Migrants"],"British Depth Study":["Anglo-Saxon","Norman","Richard","John","Henry VIII","Elizabethan"],"Period Study":["Spain","New World","British America","American West","Cold War","Middle East"],"Modern Depth Study":["Russia","Soviet","Weimar","Nazi","Mao","China","USA"],"History Skills":["Source","Interpretation","Explain","Judgement","Consequence","Significance"]},
 "RE":{"Christianity":["Christianity","Christian"],"Catholic Christianity":["Catholic"],"Islam":["Islam","Muslim"],"Judaism":["Judaism","Jewish"],"Buddhism":["Buddhism","Buddhist"],"Hinduism":["Hinduism","Hindu"],"Sikhism":["Sikhism","Sikh"],"Philosophy & Ethics":["Philosophy","Ethics","Relationships","Families","Existence of God"],"Religion, Peace & Conflict":["Crime","Punishment","Peace","Conflict","Religious Life"]}
};
function escapeHtml(v){return String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}

// V0.12.3 — Pearson Edexcel 1MA1 curriculum architecture + rebuilt Number strand.
// The six strands mirror the qualification specification; skills are intentionally
// finer-grained so mastery can later be tracked at skill rather than legacy topic level.
const MATHS_CURRICULUM={
 "Number":["Integers & place value","Four operations","Factors, multiples & primes","Powers, roots & indices","Fractions","Decimals","Standard form","Exact calculation & surds","Bounds & estimation"],
 "Algebra":["Notation & expressions","Substitution","Expanding & factorising","Algebraic fractions","Equations","Inequalities","Sequences","Coordinates & straight-line graphs","Quadratic graphs & equations","Simultaneous equations","Functions","Iteration & algebraic proof"],
 "Ratio, Proportion & Rates of Change":["Units & conversions","Ratio notation & sharing","Fractions and ratio","Percentages & percentage change","Direct proportion","Inverse proportion","Compound measures","Scale factors & similarity","Growth & decay","Rates of change"],
 "Geometry & Measures":["Angles","Properties of shapes","Perimeter & area","Circles","Volume & surface area","Transformations","Constructions & loci","Bearings","Congruence & similarity","Pythagoras","Trigonometry","Vectors"],
 "Probability":["Probability scale","Single-event probability","Sample spaces","Combined events","Tree diagrams","Venn diagrams & set notation","Relative frequency","Conditional probability"],
 "Statistics":["Sampling","Tables & charts","Averages & range","Grouped data","Scatter graphs","Time series","Histograms","Cumulative frequency","Box plots","Comparing distributions"]
};
function mathsCurriculumCount(strand){return pool("Maths").filter(q=>categoryFor(q)===strand).length}
function mathsCategoryPicker(){
 const cards=Object.entries(MATHS_CURRICULUM).map(([strand,skills])=>{const n=mathsCurriculumCount(strand),disabled=!n;return `<div class="maths-strand-card ${disabled?"curriculum-gap":""}"><button class="category-choice" data-cat="${escapeHtml(strand)}" ${disabled?"disabled":""}><b>${escapeHtml(strand)}</b><small>${n?`${n} current questions`:`Content rebuild required`}</small></button><details><summary>${skills.length} skills</summary><div class="curriculum-skills">${skills.map(x=>`<span>${escapeHtml(x)}</span>`).join("")}</div></details></div>`}).join("");
 return `<section class="profile-page"><div class="profile-nav"><button class="secondary" onclick="goHome()">← Home</button></div><div class="panel"><h2>Maths</h2><p class="muted">Pearson Edexcel GCSE (1MA1) · six specification strands. Choose a strand or use all current Maths content.</p><button class="category-choice category-all" data-cat="All">✨ All current topics</button><div class="maths-curriculum-grid">${cards}</div><p class="muted curriculum-note">Greyed strands show where the existing question bank still needs rebuilding. They are mapped now so new questions can be added to the correct skill.</p></div></section>`
}

const COURSE_OPTIONS={
 RE:["Christianity","Catholic Christianity","Islam","Judaism","Buddhism","Hinduism","Sikhism","Philosophy & Ethics","Religion, Peace & Conflict"],
 History:["Crime and punishment","Medicine in Britain","Warfare and British society","Migrants to Britain","Anglo-Saxon and Norman England","Richard I and King John","Henry VIII and his ministers","Early Elizabethan England","Spain and the New World","British America","The American West","Superpower relations and the Cold War","Conflict in the Middle East","Russia and the Soviet Union","Weimar and Nazi Germany","Mao's China","The USA: conflict at home and abroad"]
};
function ensureCourseSelections(){state.courseSelections=state.courseSelections||{};for(const sub of ["RE","History"])if(!Array.isArray(state.courseSelections[sub]))state.courseSelections[sub]=[]}
function courseMatch(q,option){const t=((q.topic||"")+" "+(q.prompt||"")+" "+(q.q||"")).toLowerCase(),o=option.toLowerCase();const m={"christianity":["christianity","christian"],"catholic christianity":["catholic"],"islam":["islam","muslim"],"judaism":["judaism","jewish"],"buddhism":["buddhism","buddhist"],"hinduism":["hinduism","hindu"],"sikhism":["sikhism","sikh"],"philosophy & ethics":["philosophy","ethics","relationship","famil","existence of god"],"religion, peace & conflict":["crime","punishment","peace","conflict","religious life"],"crime and punishment":["crime","punishment"],"medicine in britain":["medicine"],"warfare and british society":["warfare"],"migrants to britain":["migrant"],"anglo-saxon and norman england":["anglo","norman"],"richard i and king john":["richard","king john"],"henry viii and his ministers":["henry viii"],"early elizabethan england":["elizabeth"],"spain and the new world":["spain","new world"],"british america":["british america"],"the american west":["american west"],"superpower relations and the cold war":["cold war","superpower"],"conflict in the middle east":["middle east"],"russia and the soviet union":["russia","soviet"],"weimar and nazi germany":["weimar","nazi"],"mao's china":["mao","china"],"the usa: conflict at home and abroad":["usa","civil rights","vietnam"]};return (m[o]||[o]).some(k=>t.includes(k))}
function selectedCoursePool(subject,p){ensureCourseSelections();let sel=state.courseSelections[subject]||[];if(!sel.length)return p;let f=p.filter(q=>sel.some(o=>courseMatch(q,o)));return f.length?f:p}
function showCourseOptions(subject){ensureCourseSelections();let selected=state.courseSelections[subject]||[],opts=COURSE_OPTIONS[subject]||[];openOverlay("courseOptionsOverlay",`<section class="profile-page"><div class="profile-nav"><button class="secondary" onclick="goHome()">← Home</button></div><div class="panel course-options-panel"><h2>⚙️ ${escapeHtml(subject)} course options</h2><p class="muted">Select the topics your school teaches. Leave everything unticked to use all available content.</p><div class="course-options-grid">${opts.map(o=>`<label class="course-option"><input type="checkbox" value="${escapeHtml(o)}" ${selected.includes(o)?"checked":""}><span>${escapeHtml(o)}</span></label>`).join("")}</div><button class="primary" id="saveCourseOptions">Save course</button></div></section>`);document.getElementById("saveCourseOptions").onclick=()=>{state.courseSelections[subject]=[...document.querySelectorAll("#courseOptionsOverlay input:checked")].map(x=>x.value);save();closeOverlays();showCategoryPicker(subject)}}
function categoryFor(q){
 if(q.subject==="Maths"&&q.strand)return q.strand;
 let groups=CATEGORY_GROUPS[q.subject]||{},t=(q.topic||"").toLowerCase(),p=(q.prompt||"").toLowerCase();
 for(const [name,keys] of Object.entries(groups))if(keys.some(k=>t.includes(k.toLowerCase())||p.includes(k.toLowerCase())))return name;
 return q.topic||"General";
}
function categoriesFor(subject){
 let cats=[...new Set(pool(subject).map(categoryFor).filter(Boolean))];
 let preferred=Object.keys(CATEGORY_GROUPS[subject]||{});
 return ["All",...preferred.filter(x=>cats.includes(x)),...cats.filter(x=>!preferred.includes(x)).sort()];
}
function categoryPool(subject,category="All"){let p=pool(subject);return category==="All"?p:p.filter(q=>categoryFor(q)===category)}
function showCategoryPicker(subject){
 if(subject==="Maths"){openOverlay("categoryOverlay",mathsCategoryPicker());document.querySelectorAll(".category-choice:not([disabled])").forEach(b=>b.onclick=()=>start(subject,b.dataset.cat));return}
 let cats=categoriesFor(subject),buttons=cats.map(c=>`<button class="category-choice ${c==="All"?"category-all":""}" data-cat="${escapeHtml(c)}">${c==="All"?"✨ All topics":escapeHtml(c)}</button>`).join("");
 openOverlay("categoryOverlay",`<section class="profile-page"><div class="profile-nav"><button class="secondary" onclick="goHome()">← Home</button></div><div class="panel"><h2>${escapeHtml(subject)}</h2><p class="muted">Choose a category, or use <b>All topics</b> for a coverage-balanced mission.</p>${["RE","History"].includes(subject)?`<button class="secondary course-settings-btn" onclick="showCourseOptions(\'${subject}\')">⚙️ Choose my ${subject} course</button>`:""}<div class="category-grid">${buttons}</div></div></section>`);
 document.querySelectorAll(".category-choice").forEach(b=>b.onclick=()=>start(subject,b.dataset.cat));
}
function pool(subject){let p=BANK.map(normalise).filter(q=>q.subject===subject);if(["Maths","Science"].includes(subject)&&state.tiers[subject]!=="Higher")p=p.filter(q=>(q.grade||4)<=5);if(["RE","History"].includes(subject))p=selectedCoursePool(subject,p);return p}
function subjectStats(subject){const h=state.history.filter(x=>x.subject===subject).slice(-20),c=h.filter(x=>x.correct).length;return {n:h.length,acc:h.length?Math.round(c/h.length*100):0}}
function topicStats(subject){const ts=[...new Set(BANK.filter(q=>q.subject===subject).map(q=>q.topic).filter(Boolean))];return ts.map(topic=>{const h=state.history.filter(x=>x.subject===subject&&x.topic===topic).slice(-10),c=h.filter(x=>x.correct).length;return {topic,n:h.length,acc:h.length?Math.round(c/h.length*100):0}}).sort((a,b)=>(a.n?a.acc:101)-(b.n?b.acc:101))}
function weakAreas(){let out=[];["Maths","English","Science","History","Geography","German","Drama","Citizenship","Sport Science","Catering","Spanish","RE"].forEach(sub=>topicStats(sub).filter(x=>x.n>=1&&x.acc<75).slice(0,3).forEach(x=>out.push({subject:sub,...x})));return out.sort((a,b)=>a.acc-b.acc).slice(0,6)}
function bossAvailable(){return state.missions>0&&state.missions%5===0&&state.lastBoss!==state.missions}
function bossQuestions(){let weak=weakAreas(),out=[];for(const w of weak){let p=BANK.map(normalise).filter(q=>q.subject===w.subject&&q.topic===w.topic);p.sort(()=>Math.random()-.5);if(p[0]&&!out.includes(p[0]))out.push(p[0])}let all=BANK.map(normalise).filter(q=>(q.grade||4)>=4&&(q.grade||4)<=6);all.sort(()=>Math.random()-.5);for(const q of all)if(out.length<10&&!out.includes(q))out.push(q);return diversePick(out,10)}
// V0.11B.5.2 — Rare Dragon Encounter
const DRAGON_QUESTION_COUNT=20,DRAGON_REWARD=1000,DRAGON_LIVES=3,DRAGON_CHANCE=0.04;
function dragonDay(){return new Date().toISOString().slice(0,10)}
function dragonRandom(){try{let a=new Uint32Array(1);crypto.getRandomValues(a);return a[0]/4294967296}catch(e){return Math.random()}}
function dragonEligibleSubjects(){return allSubjects().filter(sub=>pool(sub).length>=5)}
function dragonQuestions(){
 let subjects=dragonEligibleSubjects(),recentAll=recentVarietyPatterns(null,160),used=new Set(),subjectCounts=new Map(),candidates=[];
 for(const sub of subjects){for(const q of pool(sub)){let pat=varietyPattern(q);if(!used.has(pat))candidates.push(q)}}
 // Prefer unseen patterns and broad subject coverage. Never repeat a question pattern.
 let out=[];
 while(out.length<DRAGON_QUESTION_COUNT&&candidates.length){
   let scored=candidates.map(q=>{let pat=varietyPattern(q),count=subjectCounts.get(q.subject)||0,score=dragonRandom()*20-count*28-(recentAll.has(pat)?35:0);return {q,pat,score}}).filter(x=>!used.has(x.pat));
   if(!scored.length)break;scored.sort((a,b)=>b.score-a.score);let pick=scored[0];out.push(pick.q);used.add(pick.pat);subjectCounts.set(pick.q.subject,(subjectCounts.get(pick.q.subject)||0)+1);candidates=candidates.filter(q=>varietyPattern(q)!==pick.pat)
 }
 // Final phase is tougher, but still only from questions already allowed by the learner's tier.
 let first=out.slice(0,15),final=out.slice(15).sort((a,b)=>(a.grade||a.difficulty||4)-(b.grade||b.difficulty||4));
 return first.concat(final)
}
function maybeRollDragon(){
 let d=dragonDay();if(state.dragon.pending||state.dragon.lastEncounterDate===d||state.missions<3||state.dragon.lastRollMission===state.missions)return false;
 state.dragon.lastRollMission=state.missions;
 if(dragonRandom()>=DRAGON_CHANCE){save();return false}
 let qs=dragonQuestions();if(qs.length<DRAGON_QUESTION_COUNT){save();return false}
 state.dragon.lastEncounterDate=d;state.dragon.pending={id:`dragon-${d}-${Date.now()}`,date:d,qs};save();return true
}
// Forced QA flag survives the cloud identity hand-off. The URL can be consumed immediately,
// but the flag remains until the learner actually starts the Dragon battle.
let FORCE_DRAGON_TEST=false;
try{
 const dp=new URLSearchParams(location.search);
 if(dp.get("dragon")==="1"||dp.get("dragonTest")==="1"){
   FORCE_DRAGON_TEST=true;sessionStorage.setItem("levelup10ForceDragon","1");
   dp.delete("dragon");dp.delete("dragonTest");
   const dq=dp.toString();history.replaceState(null,"",location.pathname+(dq?`?${dq}`:"")+location.hash);
 }else FORCE_DRAGON_TEST=sessionStorage.getItem("levelup10ForceDragon")==="1";
}catch(e){}
function renderDragon(){
 let card=document.getElementById("dragonCard"),text=document.getElementById("dragonText");if(!card||!text)return;
 // V0.11B.5.2 — retry the forced encounter after every Home render. This matters because
 // cloud sign-in swaps from the temporary/local learner state to the cloud learner state after load.
 try{
   if(FORCE_DRAGON_TEST&&!state.dragon?.pending){
     let qs=dragonQuestions();
     if(qs.length===DRAGON_QUESTION_COUNT){
       state.dragon.pending={id:`dragon-test-${Date.now()}`,date:dragonDay(),qs};save();
     }
   }
 }catch(e){}
 if(state.dragon?.pending){card.classList.remove("hidden");text.textContent=`20 mixed-subject questions • 3 Dragon lives • ${DRAGON_REWARD.toLocaleString()} coin reward`;}
 else card.classList.add("hidden")
}
function startDragon(){
 try{FORCE_DRAGON_TEST=false;sessionStorage.removeItem("levelup10ForceDragon")}catch(e){}
 let pending=state.dragon?.pending;if(!pending||!Array.isArray(pending.qs)||pending.qs.length!==DRAGON_QUESTION_COUNT)return;
 session={subject:"Dragon Encounter",qs:pending.qs,index:0,correct:0,answered:false,isReadiness:false,isBoss:false,isDragon:true,dragonLives:DRAGON_LIVES,normalLives:state.lives,recoveries:0,sessionMistakes:[]};state.dragon.pending=null;save();saveActiveSession();show("lesson");render()
}
function finishDragon(won){
 let correct=session.correct,total=session.qs.length,pct=Math.round(correct/total*100);state.lives=session.normalLives??state.lives;
 if(won){state.coins+=DRAGON_REWARD;state.dragon.defeated=(state.dragon.defeated||0)+1;$("resultTitle").textContent="Dragon defeated! 🐉🏆";$("resultScore").textContent=`${correct}/${total} correct • ${pct}%`;$("resultXP").textContent=`Legendary victory • +${DRAGON_REWARD.toLocaleString()} 🪙 Boost Coins`}
 else{state.dragon.escaped=(state.dragon.escaped||0)+1;$("resultTitle").textContent="The Dragon escaped 🐉";$("resultScore").textContent=`${correct}/${total} correct • ${pct}%`;$("resultXP").textContent="All 3 Dragon lives were lost • the 1,000 coin hoard escaped"}
 session=null;clearActiveSession();save();show("result")
}
function startBoss(){let qs=bossQuestions();if(!qs.length)return;state.lives=3;save();session={subject:"Boss Battle",qs,index:0,correct:0,answered:false,isReadiness:false,isBoss:true,recoveries:0,sessionMistakes:[]};saveActiveSession();show("lesson");render()}
function renderWeak(){const box=$("weakAreas");if(!box)return;let w=weakAreas();box.innerHTML=w.length?w.map(x=>`<div class="weakRow"><b>${x.subject}</b><span>${x.topic}</span><strong>${x.acc}%</strong></div>`).join(""):'<p class="muted">Complete some missions and weak areas will appear here.</p>'}
function renderBoss(){const b=$("bossBtn"),t=$("bossText");if(!b||!t)return;if(bossAvailable()){b.classList.remove("hidden");t.textContent="Boss Battle unlocked — 10 mixed questions from weak areas."}else{b.classList.add("hidden");let rem=5-(state.missions%5);t.textContent=`${rem} mission${rem===1?"":"s"} until the next Boss Battle.`}}
function readinessEligible(subject){if(!["Maths","Science"].includes(subject)||state.tiers[subject]==="Higher")return false;const st=subjectStats(subject),tested=topicStats(subject).filter(x=>x.n>=2);return st.n>=12&&st.acc>=75&&tested.length>=3&&tested.filter(x=>x.acc>=70).length>=3}
function readinessQuestions(subject){let p=BANK.map(normalise).filter(q=>q.subject===subject&&(q.grade||4)>=5&&(q.grade||4)<=6);p.sort(()=>Math.random()-.5);return p.slice(0,30)}

function varietyPattern(q){return [q.subject||"",q.topic||"",norm(q.prompt||"").replace(/\b\d+(?:\.\d+)?\b/g,"#").replace(/\s+/g," ").trim()].join("|")}
function recentVarietyPatterns(subject,limit=100){let set=new Set(),arr=(state.served||[]).slice().reverse();for(const r of arr){if(set.size>=limit)break;if(r.subject&&r.subject!==subject)continue;if(r.pattern)set.add(r.pattern);else if(r.fp)set.add(r.fp)}return set}
function cleanNumericDisplay(value){
 let n=Number(value);
 if(!Number.isFinite(n))return String(value).trim();
 if(Number.isInteger(n))return String(n);
 return String(Math.round(n*100)/100).replace(/\.0+$/,"").replace(/(\.\d*?)0+$/,"$1");
}
function numericDistractors(q){
 let raw=String(q.expected??"").trim(),n=Number(raw);
 if(!Number.isFinite(n))return null;
 let candidates=[n+1,n-1,n+2,n-2,n+5,n-5,n*2,n/2];
 let wrong=[];
 for(const x of candidates){
   if(!Number.isFinite(x)||x===n)continue;
   let v=cleanNumericDisplay(x);
   if(v!==cleanNumericDisplay(n)&&!wrong.includes(v))wrong.push(v)
 }
 if(wrong.length<3)return null;
 // Apply exactly the same display formatter to correct and incorrect options.
 let correct=cleanNumericDisplay(n);
 let choices=[correct,...wrong.slice(0,3)].sort(()=>Math.random()-.5);
 return {...q,kind:"mcq",choices,correctIndex:choices.indexOf(correct),expected:raw};
}
function missionMCQPool(subject,p){
 let mc=p.filter(q=>q.kind==="mcq");
 if(subject==="Maths"){
   for(const q of p.filter(q=>q.kind==="short")){
     let mq=numericDistractors(q);
     if(mq)mc.push(mq);
   }
 }
 return mc;
}
function needsDivision(subject){return subject==="Maths"&&!(state.served||[]).slice(-24).some(r=>r.subject==="Maths"&&r.topic==="Division")}
function choose(subject,n=8,category="All"){
 let p=categoryPool(subject,category),recent=recentVarietyPatterns(subject,100),mc=missionMCQPool(subject,p),sh=p.filter(q=>q.kind==="short"),wr=p.filter(q=>q.kind==="written"),out=[],usedPatterns=new Set(),topicCounts=new Map();
 if(category==="All"){
   let cats=categoriesFor(subject).filter(x=>x!=="All"),recentCats=(state.served||[]).filter(r=>r.subject===subject).slice(-50).map(r=>r.category||r.topic),ranked=cats.map(c=>({c,n:recentCats.filter(x=>x===c).length})).sort((a,b)=>a.n-b.n);
   for(const x of ranked.slice(0,Math.min(3,ranked.length))){let g=p.filter(q=>categoryFor(q)===x.c&&!usedPatterns.has(varietyPattern(q)));if(g.length){let q=g[Math.floor(Math.random()*g.length)];out.push(q);usedPatterns.add(varietyPattern(q));topicCounts.set(q.topic||"Practice",1)}}
 }
 function score(q){let pat=varietyPattern(q),topic=q.topic||"Practice",v=Math.random()*10;if(recent.has(pat))v-=120;if(usedPatterns.has(pat))v-=200;v-=(topicCounts.get(topic)||0)*35;return v}
 function add(group,count){let g=[...group];while(count>0&&g.length){g.sort((x,y)=>score(y)-score(x));let q=g.shift(),pat=varietyPattern(q),topic=q.topic||"Practice";if(out.some(x=>x.prompt===q.prompt)||usedPatterns.has(pat))continue;out.push(q);usedPatterns.add(pat);topicCounts.set(topic,(topicCounts.get(topic)||0)+1);count--}}
 add(mc,Math.max(0,Math.min(5,n-out.length)));add(sh,Math.min(2,n-out.length));add(wr,Math.min(1,n-out.length));add(p,n-out.length);
 if(out.length<n){for(const q of [...p].sort(()=>Math.random()-.5)){if(out.length>=n)break;if(!out.some(x=>x.prompt===q.prompt))out.push(q)}}
 return out.slice(0,n).sort(()=>Math.random()-.5)
}
function home(){applyAppTheme();show("home");attachHomeProfile();let pn=document.getElementById("profileName"),pa=document.getElementById("profileAvatar"),pl=document.getElementById("profileLevel");if(pn)pn.textContent=learnerName();if(pa){pa.innerHTML=avatarDecorHTML(false);}if(pl)pl.textContent="Level "+levelFromXP();$("streak").textContent=state.streak;$("xp").textContent=state.xp;$("lives").textContent=state.lives;let cb=$("coins");if(cb)cb.textContent=coinBalance();let recommended=todaySubject();$("missionTitle").textContent=recommended+" Boost";let strip=document.getElementById("schoolTodayStrip");if(strip)strip.innerHTML=todaySchoolHTML();let reason=document.getElementById("missionReason");if(reason)reason.textContent=todaysSchoolSubjects().includes(recommended)?`Recommended because you have ${recommended} today · balanced with your recent progress`:"Recommended from your recent progress";renderProgress();renderWeak();renderBoss();renderDragon();["Maths","Science"].forEach(sub=>{const b=$(sub.toLowerCase()+"Ready");if(b){b.classList.toggle("hidden",!readinessEligible(sub));b.textContent="TAKE "+sub.toUpperCase()+" HIGHER READINESS TEST"}const t=$(sub.toLowerCase()+"Tier");if(t)t.textContent=state.tiers[sub]})}
function renderProgress(){const box=$("progressCards");if(!box)return;box.innerHTML="";["Maths","English","Science","History","Geography","German","Drama","Citizenship","Sport Science","Catering","Spanish","RE"].forEach(sub=>{const st=subjectStats(sub),weak=topicStats(sub).filter(x=>x.n).slice(0,2);const d=document.createElement("div");d.className="progressCard";d.innerHTML=`<b>${sub} <em class="board">${BOARD[sub]}</em></b><strong>${st.n?st.acc+"%":"New"}</strong><small>${st.n} recent answers${weak.length?" • Focus: "+weak.map(x=>x.topic).join(", "):""}</small>`;box.appendChild(d)})}
function startReadiness(subject){const qs=readinessQuestions(subject);if(qs.length<10){alert("Keep practising first — more Higher bridge questions are needed.");return}session={subject,qs,index:0,correct:0,answered:false,isReadiness:true,isBoss:false,recoveries:0,sessionMistakes:[]};saveActiveSession();show("lesson");render()}
function start(subject=todaySubject(),category="All"){try{const qs=choose(subject,8,category);if(!qs.length)throw Error("No questions");state.lives=3;save();session={subject,category,qs,index:0,correct:0,answered:false,isReadiness:false,isBoss:false,recoveries:0,sessionMistakes:[]};saveActiveSession();show("lesson");render()}catch(e){fail("M01",e)}}
function recoveryQuestions(){let src=(session.sessionMistakes||[]).slice().reverse(),out=[];for(const q of src)if(!out.some(x=>x.prompt===q.prompt))out.push(q);let weak=weakAreas();for(const w of weak){let p=BANK.map(normalise).filter(q=>q.subject===w.subject&&q.topic===w.topic);p.sort(()=>Math.random()-.5);for(const q of p)if(out.length<3&&!out.some(x=>x.prompt===q.prompt))out.push(q)}let same=BANK.map(normalise).filter(q=>q.subject===session.subject);same.sort(()=>Math.random()-.5);for(const q of same)if(out.length<3&&!out.some(x=>x.prompt===q.prompt))out.push(q);return diversePick(out,3)}
function beginRecovery(){const qs=recoveryQuestions();session.saved={qs:session.qs,index:session.index+1,subject:session.subject,isBoss:session.isBoss};session.qs=qs;session.index=0;session.recoveryCorrect=0;session.inRecovery=true;session.answered=false;saveActiveSession();show("lesson");render()}
function finishRecovery(){const ok=session.recoveryCorrect>=2;if(ok){state.lives=1;session.recoveries++;state.coins+=25;syncAchievements();save();$("recoveryTitle").textContent="Life recovered! ❤️";$("recoveryText").textContent=`${session.recoveryCorrect}/3 correct. You earned 1 life and can continue.`;$("recoveryContinue").textContent="CONTINUE MISSION"}else{$("recoveryTitle").textContent="Recovery practice";$("recoveryText").textContent=`${session.recoveryCorrect}/3 correct. Review the explanations, then retry the Recovery Round.`;$("recoveryContinue").textContent="RETRY RECOVERY"}session.recoveryPassed=ok;show("recovery")}
function continueRecovery(){if(session.recoveryPassed){const x=session.saved;session.qs=x.qs;session.index=x.index;session.subject=x.subject;session.isBoss=x.isBoss;session.inRecovery=false;session.saved=null;if(session.index>=session.qs.length)finish();else{show("lesson");render()}}else{session.qs=recoveryQuestions();session.index=0;session.recoveryCorrect=0;session.answered=false;saveActiveSession();show("lesson");render()}}
function displayPrompt(q){let t=q.prompt||"Question";if(q.subject==="Maths"&&/^solve\s+.+?=.+[.]?$/i.test(t)&&!/[?]$/.test(t)){let lhs=(t.match(/^solve\s+(.+?)=/i)||[])[1]||"",vars=lhs.match(/[a-z]/ig)||[],v=vars.length?vars[0].toLowerCase():"the unknown";t=t.replace(/[.]?$/,"")+". What is "+v+"?"}return t}
function render(){try{const q=session&&session.qs?session.qs[session.index]:null;if(!q)return finish();if(!session.renderedKeys)session.renderedKeys={};let rk=`${session.inRecovery?"R":"M"}-${session.index}-${questionFingerprint(q)}`;if(!session.renderedKeys[rk]){recordServed(q);session.renderedKeys[rk]=1;}$("lessonSubject").textContent=session.isDragon?`🐉 DRAGON ENCOUNTER • ❤️ ${session.dragonLives} • ${q.subject} • ${boardTag(q)} • ${q.topic||"Practice"} • Grade ${q.grade||""}`:`${session.inRecovery?"RECOVERY ROUND • ":(session.isBoss?"BOSS BATTLE • ":(session.isReadiness?"Higher Readiness • ":""))}${session.subject} • ${boardTag(q)} • ${q.topic||"Practice"} • Grade ${q.grade||""}`;$("progressText").textContent=`Question ${session.index+1} of ${session.qs.length}`;$("questionText").textContent=displayPrompt(q);$("feedback").innerHTML="";$("nextBtn").classList.add("hidden");const a=$("answerArea");a.innerHTML="";session.answered=false;session.resumeFeedback=null;session.resumeAnswerIndex=null;session.resumeAnswerValue=null;saveActiveSession();if(q.kind==="mcq"){q.choices.forEach((v,i)=>{const b=document.createElement("button");b.className="answer";b.textContent=v;b.onclick=()=>mark(i,v);a.appendChild(b)})}else{const t=document.createElement(q.kind==="written"?"textarea":"input");t.className="typed";t.rows=4;t.placeholder=q.kind==="written"?"Write a short GCSE answer…":"Type your answer";a.appendChild(t);const b=document.createElement("button");b.className="primary";b.textContent="CHECK ANSWER";b.onclick=()=>mark(null,t.value);a.appendChild(b)}}catch(e){fail("M02",e)}}
const SYNONYMS={effect:["effect","impact","response","reaction"],audience:["audience","viewer","spectator","reader"],evidence:["evidence","example","quotation","quote","data","figure"],because:["because","therefore","so","as a result","this means","which means"],method:["method","technique","device","choice","feature"],meaning:["meaning","suggests","implies","shows","conveys"],tension:["tension","suspense","nervous","uneasy","danger"],reliable:["reliable","dependable","consistent"],bias:["bias","biased","unrepresentative"],impact:["impact","effect","consequence","result"],process:["process","mechanism","how"],viewpoint:["viewpoint","opinion","perspective","argument"],judgement:["judgement","judgment","conclusion"],voice:["voice","vocal","tone","pitch","pace","volume","pause"],technique:["technique","method","skill","choice"],intention:["intention","purpose","aim"],rights:["rights","freedoms"],responsibility:["responsibility","duty","obligation"],law:["law","legal","rule"],performer:["performer","athlete","player"],training:["training","exercise","programme","program"],safety:["safety","safe","risk","hazard"],customer:["customer","guest","client"],nutrition:["nutrition","nutritional","nutrient","diet"],allergy:["allergy","allergic","allergen"],intolerance:["intolerance","intolerant"],"cross contamination":["cross contamination","cross-contamination","contamination"],gestern:["gestern"],weil:["weil","denn","da"],ayer:["ayer"],porque:["porque","ya que"]};
function hasConcept(text,key){const t=norm(text),k=norm(key),vs=SYNONYMS[k]||[k];return vs.some(x=>t.includes(norm(x)))}
function textRubric(q,v){const text=norm(v),words=text.split(" ").filter(Boolean),keys=(q.keywords||toks(q.expected)).map(norm).filter(Boolean),hits=keys.filter(k=>hasConcept(text,k)),misses=keys.filter(k=>!hasConcept(text,k));let reasoning=/\b(because|therefore|so that|as a result|this means|which means|weil|denn|porque|ya que)\b/.test(text);let score=(keys.length?hits.length/keys.length:.35)*.7+(reasoning?.15:0)+(words.length>=12?.1:0)+(words.length>=25?.05:0);if(["German","Spanish"].includes(q.subject))score=(keys.length?hits.length/keys.length:.35)*.65+(words.length>=4?.2:0)+(words.length>=8?.15:0);let band=score>=.82?"Strong":score>=.58?"Secure":score>=.30?"Developing":"Needs work",accepted=score>=.48||(keys.length<=2&&hits.length>=1&&words.length>=5);let plus=[];if(hits.length)plus.push("Recognised: "+hits.slice(0,3).join(", "));if(reasoning)plus.push("Reasoning link used");let next=[];if(misses.length)next.push("Consider adding: "+misses.slice(0,2).join(", "));if(!reasoning&&!["German","Spanish"].includes(q.subject))next.push("Explain why using because/therefore");if(words.length<8)next.push("Develop the answer a little further");return{accepted,band,score:Math.round(score*100),plus,next}}
function writtenFeedback(r){return `<b>${r.band}</b> — ${r.score}% of the response target${r.plus.length?"<br>✓ "+r.plus.join(" • "):""}${r.next.length?"<br>→ "+r.next.join(" • "):""}`}
function judge(q,i,v){if(q.kind==="mcq")return i===q.correctIndex;const cleaned=String(v??"").trim().replace(/^\s*[a-z]\s*=\s*/i,"");const A=Number(norm(cleaned)),B=Number(norm(q.expected));if(norm(cleaned)!==""&&Number.isFinite(A)&&Number.isFinite(B))return Math.abs(A-B)<1e-8;if(q.kind==="short")return [q.expected,...(q.accept||q.accepted||[])].filter(x=>x!=null).some(x=>closeText(v,x));return textRubric(q,v).accepted}
function lockCurrentAnswer(){document.querySelectorAll("#lesson input,#lesson textarea,#lesson select,.answer").forEach(el=>{el.disabled=true;el.classList.add("answer-locked");el.setAttribute("aria-disabled","true")});document.querySelectorAll("#lesson button").forEach(el=>{if(el.id!=="nextBtn"&&!el.classList.contains("back")){el.disabled=true;el.classList.add("check-locked")}})}
function mark(i,v){if(session.answered)return;session.answered=true;lockCurrentAnswer();const q=session.qs[session.index],rubric=q.kind==="written"?textRubric(q,v):null,ok=rubric?rubric.accepted:judge(q,i,v);state.totalAnswered++;if(ok)state.totalCorrect++;document.querySelectorAll(".answer").forEach((b,j)=>{b.disabled=true;if(q.kind==="mcq"&&j===q.correctIndex)b.classList.add("correctChoice");if(q.kind==="mcq"&&j===i&&!ok)b.classList.add("wrongChoice")});if(ok){if(session.inRecovery)session.recoveryCorrect++;else session.correct++;state.xp+=session.inRecovery?0:10;$("feedback").innerHTML=`<div class="good"><b>${rubric?rubric.band:"Correct ✓"}</b><p>${rubric?writtenFeedback(rubric)+"<br><br>":""}${q.explanation}</p></div>`}else{if(session.isDragon)session.dragonLives=Math.max(0,(session.dragonLives??DRAGON_LIVES)-1);else if(!session.isReadiness&&!session.inRecovery)state.lives=Math.max(0,state.lives-1);if(!session.sessionMistakes)session.sessionMistakes=[];session.sessionMistakes.push(q);state.mistakes.push({subject:q.subject,topic:q.topic,date:Date.now()});state.mistakes=state.mistakes.slice(-100);const ans=q.kind==="mcq"?q.choices[q.correctIndex]:(q.kind==="written"?"Use the feedback below":(q.expected??"See guidance"));$("feedback").innerHTML=`<div class="retry"><b>${rubric?rubric.band:"Not quite"}</b><p>${rubric?writtenFeedback(rubric):"<b>Correct answer:</b> "+ans}</p><p>${q.explanation}</p></div>`}state.history.push({date:Date.now(),subject:q.subject,topic:q.topic,grade:q.grade||q.difficulty||4,category:categoryFor(q),correct:ok});state.history=state.history.slice(-500);session.answered=true;session.resumeFeedback=$("feedback").innerHTML;session.resumeAnswerIndex=i;session.resumeAnswerValue=v;save();$("nextBtn").classList.remove("hidden")}
function finish(){if(session?.isDragon)return finishDragon(true);const pct=Math.round(session.correct/session.qs.length*100),d=new Date().toISOString().slice(0,10);if(session.isReadiness){state.readiness[session.subject]=pct;if(pct>=80){state.tiers[session.subject]="Higher";state.xp+=100;$("resultScore").textContent=`${session.correct}/${session.qs.length} correct • ${pct}%`;$("resultXP").textContent=`Higher pathway unlocked • +100 XP`}else{$("resultScore").textContent=`${session.correct}/${session.qs.length} correct • ${pct}%`;$("resultXP").textContent="80% needed • weak topics will return in practice"}}else if(session.isBoss){state.lastBoss=state.missions;if(pct>=80){state.bossWins++;state.xp+=100;state.coins+=100;syncAchievements(true);$("resultScore").textContent=`${session.correct}/${session.qs.length} correct • ${pct}%`;$("resultXP").textContent="Boss defeated! 👑 +100 XP"}else{$("resultScore").textContent=`${session.correct}/${session.qs.length} correct • ${pct}%`;$("resultXP").textContent="Boss survives — 80% needed. Missed topics will return."}}else{state.missions++;state.xp+=50;let coinReward=missionCoinReward();state.coins+=coinReward;if(state.lastDate!==d){state.streak++;state.lastDate=d}syncAchievements(true);$("resultScore").textContent=`${session.correct}/${session.qs.length} correct • ${pct}%`;$("resultXP").textContent=`+50 XP • +${coinReward} 🪙 • ${session.subject} mission complete`;maybeRollDragon()}$("resultTitle").textContent=session?.isBoss?"Boss Battle complete! 👑":(session?.isReadiness?"Readiness complete!":"Mission complete! 🎉");if(!session.isReadiness)state.lives=3;session=null;clearActiveSession();save();show("result")}
function fail(c,e){console.error(c,e);$("fatalError").innerHTML=`<h2>Something went wrong</h2><p>Error <b>${c}</b></p><button onclick="location.reload()" class="primary">RELOAD</button>`;$("fatalError").classList.remove("hidden")}
function pct(n,d){return d?Math.round(n*100/d):0}
function allSubjects(){return ["Maths","English","Science","History","Geography","German","Spanish","Drama","Citizenship","Sport Science","Catering","RE"]}
function progressRows(){
  let hist=Array.isArray(state.history)?state.history:[];
  return allSubjects().map(subject=>{
    let rows=hist.filter(x=>x.subject===subject);
    let recent=rows.slice(-30), previous=rows.slice(-60,-30);
    let correct=recent.filter(x=>x.correct===true||x.ok===true).length;
    let pc=previous.filter(x=>x.correct===true||x.ok===true).length;
    let acc=pct(correct,recent.length), old=pct(pc,previous.length);
    return {subject,attempts:recent.length,accuracy:acc,change:recent.length&&previous.length?acc-old:null};
  });
}
function topicProgress(){
  let hist=Array.isArray(state.history)?state.history:[];
  let map={};
  hist.slice(-400).forEach(x=>{
    if(!x.subject||!x.topic)return;
    let k=x.subject+"||"+x.topic;
    if(!map[k])map[k]={subject:x.subject,topic:x.topic,n:0,c:0};
    map[k].n++; if(x.correct===true||x.ok===true)map[k].c++;
  });
  return Object.values(map).map(x=>({...x,accuracy:pct(x.c,x.n)}));
}
function weeklySummary(){
  let hist=Array.isArray(state.history)?state.history:[];
  let since=Date.now()-7*86400000;
  let rows=hist.filter(x=>{
    let t=x.date||x.ts||x.time||0;
    if(typeof t==="string")t=Date.parse(t)||0;
    return t>=since;
  });
  let correct=rows.filter(x=>x.correct===true||x.ok===true).length;
  return {attempts:rows.length,accuracy:pct(correct,rows.length)};
}
function progressHTML(){
  let rows=progressRows(), topics=topicProgress(), week=weeklySummary();
  let mastered=topics.filter(x=>x.n>=3&&x.accuracy>=80).length;
  let weak=[...topics].filter(x=>x.n>=2).sort((a,b)=>a.accuracy-b.accuracy).slice(0,5);
  let improving=[...rows].filter(x=>x.change!==null&&x.change>0).sort((a,b)=>b.change-a.change).slice(0,3);
  let boss=state.bossWins||0, streak=state.streak||0, xp=state.xp||0;
  let subjectCards=rows.map(r=>`<div class="progress-row"><div><b>${r.subject}</b><small>${r.attempts?`${r.attempts} recent questions`:"Not enough data yet"}</small></div><div class="progress-score">${r.attempts?r.accuracy+"%":"—"} ${r.change===null?"":`<span class="${r.change>=0?"up":"down"}">${r.change>=0?"+":""}${r.change}%</span>`}</div></div>`).join("");
  let weakHTML=weak.length?weak.map(x=>`<div class="mini-row"><b>${x.subject}</b> · ${x.topic}<span>${x.accuracy}%</span></div>`).join(""):"Complete more missions and weak areas will appear here.";
  let impHTML=improving.length?improving.map(x=>`<div class="mini-row"><b>${x.subject}</b><span class="up">+${x.change}%</span></div>`).join(""):"Complete more missions to build a comparison.";
  return `<section class="progress-page">
    <div class="progress-head"><button class="secondary" onclick="goHome()">← Home</button><div><h2>My Progress</h2><p>See what is improving and what to practise next.</p></div></div>
    <div class="stat-grid">
      <div class="stat-card"><b>${xp}</b><span>Total XP</span></div>
      <div class="stat-card"><b>${streak}</b><span>Day streak</span></div>
      <div class="stat-card"><b>${boss}</b><span>Boss wins</span></div>
      <div class="stat-card"><b>${mastered}</b><span>Topics mastered</span></div>
    </div>
    <div class="panel"><h3>This week</h3><div class="big-metric">${week.attempts}</div><p>questions attempted · ${week.attempts?week.accuracy+"% accuracy":"start a mission to build your report"}</p></div>
    <div class="panel"><h3>Subjects</h3>${subjectCards}</div>
    <div class="panel"><h3>Biggest improvements</h3>${impHTML}</div>
    <div class="panel"><h3>Focus next</h3>${weakHTML}</div>
    <div class="panel parent-panel"><div class="parent-title"><div><h3>Parent view</h3><p>A simple weekly snapshot for a parent or carer.</p></div><button onclick="toggleParent()">Open</button></div>
      <div id="parentDetail" hidden>
        <div class="parent-summary"><b>${week.attempts}</b> questions this week at <b>${week.accuracy}%</b> accuracy.</div>
        <h4>Recommended focus</h4>${weakHTML}
        <p class="privacy-note">This version stays on this device. No child data is uploaded or shared.</p>
      </div>
    </div>
  </section>`;
}
function showProgress(){session=null;openOverlay("progressOverlay",progressHTML());}
function toggleParent(){let el=document.getElementById("parentDetail");if(el)el.hidden=!el.hidden}

document.addEventListener("DOMContentLoaded",()=>{let profileButton=document.getElementById("profileLaunch");if(profileButton)profileButton.onclick=showProfile;$("startBtn").onclick=()=>start(($("missionTitle").textContent||"Maths Boost").replace(/ Boost$/,""));$("nextBtn").onclick=()=>{if(session.inRecovery){session.index++;if(session.index>=session.qs.length)finishRecovery();else render();return}if(session.isDragon&&session.dragonLives===0){finishDragon(false);return}if(!session.isDragon&&!session.isReadiness&&state.lives===0){beginRecovery();return}session.index++;render()};$("lessonBack").onclick=()=>{session=null;clearActiveSession();home()};$("resultHome").onclick=home;document.querySelectorAll("[data-subject]").forEach(b=>b.onclick=()=>showCategoryPicker(b.dataset.subject));$("mathsReady").onclick=()=>startReadiness("Maths");$("scienceReady").onclick=()=>startReadiness("Science");$("bossBtn").onclick=startBoss;let db=$("dragonBtn");if(db)db.onclick=startDragon;$("recoveryContinue").onclick=continueRecovery;if(session&&session.qs&&session.index<session.qs.length){const wasAnswered=!!session.answered,fb=session.resumeFeedback,ai=session.resumeAnswerIndex,av=session.resumeAnswerValue;show("lesson");render();if(wasAnswered){session.answered=true;if(fb)$("feedback").innerHTML=fb;if(session.qs[session.index]?.kind==="mcq"&&Number.isInteger(ai)){document.querySelectorAll(".answer").forEach((b,j)=>{if(j===session.qs[session.index].correctIndex)b.classList.add("correctChoice");if(j===ai&&ai!==session.qs[session.index].correctIndex)b.classList.add("wrongChoice")})}else{const t=document.querySelector("#answerArea .typed");if(t&&av!=null)t.value=av}lockCurrentAnswer();$("nextBtn").classList.remove("hidden")}}else{session=null;clearActiveSession();home()}if("serviceWorker"in navigator)navigator.serviceWorker.register("./sw.js").catch(()=>{})});
function learnerName(){return state.profile&&state.profile.name?state.profile.name:"Learner"}
function learnerAvatar(){return state.profile&&state.profile.avatar?state.profile.avatar:"🎓"}
function levelFromXP(){return Math.max(1,Math.floor((state.xp||0)/250)+1)}

function estimatedGrade(subject){
 let h=state.history.filter(x=>x.subject===subject).slice(-40);
 if(h.length<8)return {label:"Building…",detail:`${h.length}/8 answers for first estimate`};
 let byGrade={};for(const x of h){let g=Math.max(4,Math.min(9,Number(x.grade)||4));(byGrade[g]??=[]).push(x.correct?1:0)}
 let best=3;
 for(let g=4;g<=9;g++){let evidence=h.filter(x=>(Number(x.grade)||4)>=g),acc=evidence.length?evidence.reduce((a,x)=>a+(x.correct?1:0),0)/evidence.length:0;if(evidence.length>=4&&acc>=.65)best=g}
 let overall=h.reduce((a,x)=>a+(x.correct?1:0),0)/h.length;
 if(best<4&&overall>=.55)best=4;
 if(["Maths","Science"].includes(subject)&&state.tiers[subject]!=="Higher")best=Math.min(5,best);
 best=Math.max(3,Math.min(9,best));
 return {label:String(best),detail:`Based on ${h.length} recent answers · ${Math.round(overall*100)}% accuracy`};
}
function vocationalEstimate(subject){
 let h=state.history.filter(x=>x.subject===subject).slice(-40);
 if(h.length<8)return {label:"Building…",detail:`${h.length}/8 answers for first estimate`};
 let acc=h.reduce((a,x)=>a+(x.correct?1:0),0)/h.length,label=acc>=.85?"Distinction*":acc>=.75?"Distinction":acc>=.65?"Merit":acc>=.5?"Pass":"Working towards Pass";
 return {label,detail:`GCSE Boost estimate · ${Math.round(acc*100)}% recent accuracy`};
}
function gradeCardsHTML(){
 return ["Maths","English","Science","History","Geography","German","Drama","Citizenship","Sport Science","Catering","Spanish","RE"].map(sub=>{let e=["Sport Science","Catering"].includes(sub)?vocationalEstimate(sub):estimatedGrade(sub);return `<div class="grade-row"><span>${escapeHtml(sub)}</span><div><b>${escapeHtml(e.label)}</b><small>${escapeHtml(e.detail)}</small></div></div>`}).join("");
}

function schoolScheduleHTML(){
 let rows=SCHOOL_DAYS.map(day=>{let selected=state.schoolSchedule?.[day]||[];return `<div class="schedule-day"><h4>${day}</h4><div class="schedule-pills">${selected.length?selected.map((sub,i)=>`<span class="lesson-pill">${escapeHtml(sub)} <button onclick="removeSchoolLesson('${day}',${i})" aria-label="Remove ${escapeHtml(sub)}">×</button></span>`).join(""):`<span class="muted">No lessons added</span>`}</div><div class="schedule-add"><select id="add-${day}"><option value="">Add subject…</option>${SCHOOL_SUBJECTS.map(x=>`<option>${escapeHtml(x)}</option>`).join("")}</select><button class="secondary" onclick="addSchoolLesson('${day}')">Add</button></div></div>`}).join("");
 return `<div class="panel school-schedule-panel"><div class="schedule-title"><div><h3>🏫 My School Week</h3><p class="privacy-note">Add your lessons and GCSE Boost will use today's subjects when choosing your daily mission.</p></div></div>${rows}</div>`;
}
function addSchoolLesson(day){let sel=document.getElementById("add-"+day),sub=sel?.value;if(!sub)return;state.schoolSchedule=state.schoolSchedule||{};state.schoolSchedule[day]=state.schoolSchedule[day]||[];state.schoolSchedule[day].push(sub);save();showProfile()}
function removeSchoolLesson(day,index){if(!Array.isArray(state.schoolSchedule?.[day]))return;state.schoolSchedule[day].splice(index,1);save();showProfile()}
function profileHTML(){let rows=progressRows(),topics=topicProgress(),mastered=topics.filter(x=>x.n>=3&&x.accuracy>=80).length,best=[...rows].filter(x=>x.attempts).sort((a,b)=>b.accuracy-a.accuracy)[0],tier=x=>(state.tiers&&state.tiers[x])||(x==="Maths"||x==="Science"?"Foundation":"GCSE");return `<section class="profile-page profile-redesign"><div class="profile-shop-head"><div><small>MY GCSE BOOST</small><h2>👤 PROFILE</h2><p>Progress, school week and rewards in one place.</p></div><button class="secondary" onclick="goHome()">← Home</button></div><div class="profile-nav"><button class="secondary" onclick="goProgress()">📈 Full Progress</button></div><div class="profile-tabs">
<button class="profile-tab active" onclick="profileTab('overview',this)">Overview</button>
<button class="profile-tab" onclick="profileTab('school',this)">School Week</button>
<button class="profile-tab" onclick="profileTab('grades',this)">Grades</button>
<button class="profile-tab" onclick="profileTab('rewards',this)">Rewards</button>
</div><div class="profile-tab-panel active" data-profile-panel="overview"><div class="profile-hero"><button class="avatar-big decorated-avatar" onclick="editProfile()">${avatarDecorHTML(true)}</button><div><h2>${learnerName()}</h2><p>Level ${levelFromXP()} · ${state.xp||0} XP</p><button class="text-btn" onclick="editProfile()">Edit profile</button></div></div><div class="panel profile-account-panel"><h3>☁️ LevelUp10 Account</h3><p class="privacy-note">Cloud sign-in, sync and learner profiles.</p><button class="full-btn" onclick="window.showCloudAccount&&window.showCloudAccount()">☁️ Cloud account</button><button class="full-btn secondary" onclick="showAccounts()">⚙️ Switch learner / Beta</button></div><div class="stat-grid"><div class="stat-card"><b>🪙 ${coinBalance()}</b><span>Boost Coins${isTestLearner()?" · TEST":""}</span></div><div class="stat-card"><b>🔥 ${state.streak||0}</b><span>Day streak</span></div><div class="stat-card"><b>🏆 ${state.bossWins||0}</b><span>Boss wins</span></div><div class="stat-card"><b>⭐ ${state.xp||0}</b><span>Total XP</span></div><div class="stat-card"><b>✅ ${mastered}</b><span>Topics mastered</span></div></div><div class="panel"><h3>My pathway</h3><div class="path-row"><span>🧮 Maths</span><b>${tier("Maths")}</b></div><div class="path-row"><span>🧪 Science</span><b>${tier("Science")}</b></div><p class="privacy-note">Higher is an in-app learning milestone. School decides exam tier entry.</p></div></div><div class="profile-tab-panel" data-profile-panel="school">${schoolScheduleHTML()}</div>
<div class="profile-tab-panel" data-profile-panel="grades"><div class="panel grade-panel"><h3>📊 Estimated current grades</h3><p class="privacy-note">GCSE Boost estimates based on recent accuracy and question difficulty — not an official school predicted grade.</p><div class="grade-list">${gradeCardsHTML()}</div></div></div><div class="profile-tab-panel" data-profile-panel="rewards"><div class="panel"><h3>🏆 Achievement Progress</h3><p class="privacy-note">Achievements level up automatically while you learn and award Boost Coins.</p>${achievementHTML()}</div><div class="panel"><h3>Learning snapshot</h3><div class="mini-row"><span>Strongest recent subject</span><b>${best?best.subject:"Keep practising"}</b></div><div class="mini-row"><span>Current lives</span><b>❤️ ${state.lives??3}</b></div><button class="full-btn" onclick="goProgress()">Open detailed progress →</button></div><div class="panel future-card"><h3>Friends & Battles</h3><p>Private friends, leaderboards and head-to-head challenges will connect here when cloud accounts are added.</p><div class="coming-row"><span>👥 Friends</span><b>Coming soon</b></div><div class="coming-row"><span>⚔️ Battle record</span><b>Coming soon</b></div></div></div></section>`}
function profileTab(name,btn){document.querySelectorAll("[data-profile-panel]").forEach(x=>x.classList.toggle("active",x.dataset.profilePanel===name));document.querySelectorAll(".profile-tab").forEach(x=>x.classList.remove("active"));if(btn)btn.classList.add("active");}
function showProfile(){session=null;openOverlay("profileOverlay",profileHTML());}
function editProfile(){let n=prompt("Profile name",learnerName()==="Learner"?"":learnerName());if(n===null)return;n=n.trim().slice(0,24)||"Learner";let choices=["🎓","🚀","🦊","🐼","🦁","🐯","🦄","⚡"],a=prompt("Choose an avatar: "+choices.join(" "),learnerAvatar());if(!choices.includes(a))a=learnerAvatar();state.profile={...(state.profile||{}),name:n,avatar:a};save();showProfile()}
function attachHomeProfile(){setTimeout(()=>{let a=document.getElementById("app")||document.querySelector("main.app")||document.querySelector(".app"),existing=document.getElementById("profileLaunch");if(existing){existing.onclick=showProfile;return}if(!a)return;let b=document.createElement("button");b.id="profileLaunch";b.className="profile-launch";b.innerHTML=`<span class="profile-mini-avatar">${learnerAvatar()}</span><span><b>${learnerName()}</b><small>Level ${levelFromXP()} · View profile</small></span><span>›</span>`;b.onclick=showProfile;a.prepend(b)},0)}



function closeOverlays(){document.querySelectorAll(".app-overlay").forEach(x=>x.remove())}
function openOverlay(id,html){closeOverlays();document.querySelectorAll(".screen").forEach(x=>x.classList.add("hidden"));let o=document.createElement("div");o.id=id;o.className="app-overlay";o.innerHTML=html;document.body.appendChild(o);window.scrollTo(0,0)}
function goHome(){session=null;clearActiveSession();closeOverlays();home();window.scrollTo(0,0)}
function goProgress(){session=null;showProgress()}
function goProfile(){session=null;showProfile()}

// V0.11B.4.2 — cloud-first onboarding.
// Never let the legacy device-only welcome screen take over a cloud build.
window.addEventListener("load",()=>{
  if(!activeLearner()){
    document.getElementById("accountWelcome")?.remove();
    setTimeout(()=>{ if(typeof window.showCloudAccount==="function") window.showCloudAccount(); },0);
  }
});

// V0.11B.4 — Real Learner Accounts bridge.
// A signed-in cloud learner starts with a clean learning state and keeps a stable
// learner ID derived from the Supabase account UUID. Existing mission-resume logic is untouched.
function ensureCloudLocalLearner(userId,name,avatar){
  const safeName=String(name||"Learner").trim().slice(0,24)||"Learner";
  const safeAvatar=avatar||"🎓";
  const hex=String(userId||"").replace(/[^a-f0-9]/gi,"").toUpperCase();
  const cloudLearnerId=hex.length>=8?`L-${hex.slice(0,4)}-${hex.slice(4,8)}`:makeLearnerId();
  if(!accounts.learners[cloudLearnerId]){
    accounts.learners[cloudLearnerId]={id:cloudLearnerId,name:safeName,avatar:safeAvatar,cloudLearnerId,cloudUserId:userId||null,created:new Date().toISOString()};
  }else{
    accounts.learners[cloudLearnerId]={...accounts.learners[cloudLearnerId],name:safeName,avatar:safeAvatar,cloudLearnerId,cloudUserId:userId||accounts.learners[cloudLearnerId].cloudUserId||null};
  }
  accounts.active=cloudLearnerId;
  saveAccounts(accounts);
  KEY=learnerStateKey(cloudLearnerId);
  document.getElementById("accountWelcome")?.remove();
  return cloudLearnerId;
}

window.gcseBoostConfigureCloudLearner=function({userId,name,avatar}={}){
  const clean=fresh();
  const safeName=String(name||"Learner").trim().slice(0,24)||"Learner";
  const allowed=["🎓","🚀","⭐","🦊","🐼","🦁","🐯","🦄","⚡"];
  const safeAvatar=allowed.includes(avatar)?avatar:"🎓";
  const cloudLearnerId=ensureCloudLocalLearner(userId,safeName,safeAvatar);
  Object.assign(state,clean,{profile:{name:safeName,avatar:safeAvatar,cloudLearnerId},schoolSchedule:{Monday:[],Tuesday:[],Wednesday:[],Thursday:[],Friday:[]},courseSelections:{}});
  save();
  // Defensive: cloud initialisation must not replace a mission restored at startup.
  try{
    if(session&&session.qs&&session.index<session.qs.length){
      show("lesson");
    }else{
      home();
    }
  }catch(e){}
  return cloudLearnerId;
};

// V0.11B.4.1 — apply cloud identity without resetting learning progress.
window.gcseBoostApplyCloudProfileIdentity=function({userId,name,avatar}={}){
  const safeName=String(name||"Learner").trim().slice(0,24)||"Learner";
  const allowed=["🎓","🚀","⭐","🦊","🐼","🦁","🐯","🦄","⚡"];
  const safeAvatar=allowed.includes(avatar)?avatar:(state?.profile?.avatar||"🎓");
  const cloudLearnerId=ensureCloudLocalLearner(userId,safeName,safeAvatar);
  state.profile={...(state.profile||{}),name:safeName,avatar:safeAvatar,cloudLearnerId};
  try{localStorage.setItem(KEY,JSON.stringify(state))}catch(e){}
  // V0.11B.4.2.2 — identity refresh must never knock an active mission back Home.
  // DOMContentLoaded already restores/renders the saved session; leave that screen intact.
  try{
    if(session&&session.qs&&session.index<session.qs.length){
      show("lesson");
    }else{
      home();
    }
  }catch(e){}
  return cloudLearnerId;
};

window.gcseBoostCloudLearnerId=function(){return state?.profile?.cloudLearnerId||activeLearner()?.cloudLearnerId||activeLearner()?.id||"—"};
